<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {scheduleApi} from '../schedules'
const courses=ref<any[]>([]),loading=ref(false),error=ref(''),school=ref(false)
async function load(){loading.value=true;error.value='';try{const r=await scheduleApi('student/courses');courses.value=r.courses;school.value=Boolean(r.school_mode)}catch(e){courses.value=[];error.value=e instanceof Error?e.message:'Unable to load subjects.'}finally{loading.value=false}}
onMounted(load)
</script>
<template><section class="subjects-panel"><div class="subjects-heading"><h2>{{school?'Class subjects':'Courses in your semester'}}</h2><button type="button" class="secondary" :disabled="loading" @click="load">Refresh</button></div><p v-if="loading" role="status">Loading subjects…</p><p v-else-if="error" class="error" role="alert">{{error}}</p><p v-else-if="!courses.length">No subjects are available for your current academic assignment. Contact your administrator if you need help.</p><article v-for="item in courses" :key="item.offering_id"><div><strong>{{item.course_name}}</strong><small>{{item.course_code}}{{school?'':' · '+item.credits+' credits · Section '+item.section}}</small></div><span>{{item.professor||'Teacher not assigned'}}</span></article></section></template>
<style scoped>.subjects-panel{padding:18px;border:1px solid #dce6df;border-radius:12px;background:white;color:#243e33;min-width:0}.subjects-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.subjects-heading h2{font-size:18px;margin:0}.subjects-heading button{width:auto;margin:0;padding:10px 14px;font-size:13px;min-height:44px}.subjects-panel>p{font-size:13px;line-height:1.6}.subjects-panel article{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;padding:16px 0;border-bottom:1px solid #dce6df;font-size:14px;overflow-wrap:anywhere}.subjects-panel article:last-child{border-bottom:0}.subjects-panel article>div{min-width:0}.subjects-panel small{display:block;margin-top:5px;font-size:12px;color:#62786b}.subjects-panel article>span{color:#62786b;font-size:13px}.subjects-heading button:focus-visible{outline:2px solid #21896f;outline-offset:2px}</style>
